<?php
require_once 'config/database.php';start_session();$error='';$data=['fullname'=>$_SESSION['fullname']??'','email'=>'','subject'=>'','message'=>''];
if($_SERVER['REQUEST_METHOD']==='POST') {
 verify_csrf();foreach($data as $k=>$v)$data[$k]=trim($_POST[$k]??'');
 if(!$data['fullname']||!filter_var($data['email'],FILTER_VALIDATE_EMAIL)||!$data['subject']||!$data['message'])$error='Vui lòng điền đủ thông tin và email hợp lệ.';
 elseif(mb_strlen($data['fullname'])>100||strlen($data['email'])>150||mb_strlen($data['subject'])>200||mb_strlen($data['message'])>5000)$error='Họ tên tối đa 100, tiêu đề 200 và nội dung 5.000 ký tự.';
 elseif(time()-($_SESSION['last_contact']??0)<30)$error='Vui lòng chờ 30 giây trước khi gửi lời nhắn tiếp theo.';
 if(!$error){db_run('INSERT INTO contact_messages(fullname,email,subject,message) VALUES (?,?,?,?)',array_values($data));$_SESSION['last_contact']=time();flash('Đã gửi lời nhắn. Cửa hàng đã nhận yêu cầu của bạn.');header('Location: contact.php');exit;}
}
$page_title='Liên hệ · '.setting('site_name');include 'includes/header.php';
?>
<section class="page-heading"><div class="container"><p class="eyebrow">VALISTORE / LIÊN HỆ</p><h1><?= e(setting('contact_title')) ?></h1><p><?= e(setting('contact_intro')) ?></p></div></section><div class="container contact-layout"><div><h2>Kết nối với ValiStore</h2><dl class="contact-detail"><dt>Điện thoại</dt><dd><a href="tel:<?= e(preg_replace('/[^+0-9]/','',setting('phone'))) ?>"><?= e(setting('phone')) ?></a></dd><dt>Email</dt><dd><a href="mailto:<?= e(setting('email')) ?>"><?= e(setting('email')) ?></a></dd><dt>Địa chỉ</dt><dd><?= e(setting('address')) ?></dd><dt>Giờ làm việc</dt><dd><?= e(setting('hours')) ?></dd></dl><a class="text-link" href="faq.php">Xem câu hỏi thường gặp <i aria-hidden="true" class="bi bi-arrow-up-right"></i></a></div><div><?php show_flash();if($error): ?><div class="alert alert-danger"><?= e($error) ?></div><?php endif ?><form method="post" class="contact-form"><?= csrf_field() ?><div class="row g-3"><?php foreach(['fullname'=>'Họ và tên','email'=>'Email','subject'=>'Tiêu đề'] as $k=>$label): ?><div class="<?= $k==='subject'?'col-12':'col-md-6' ?>"><label for="<?= $k ?>" class="form-label"><?= $label ?></label><input class="form-control" id="<?= $k ?>" name="<?= $k ?>" type="<?= $k==='email'?'email':'text' ?>" required maxlength="<?= $k==='fullname'?100:($k==='email'?150:200) ?>" value="<?= e($data[$k]) ?>"></div><?php endforeach ?><div class="col-12"><label for="message" class="form-label">Lời nhắn của bạn</label><textarea class="form-control" id="message" name="message" required rows="6" maxlength="5000" placeholder="Nếu cần hỗ trợ đơn hàng, vui lòng ghi mã đơn."><?= e($data['message']) ?></textarea></div><div class="col-12"><p class="form-help">Thông tin được lưu để cửa hàng tiếp nhận và phản hồi yêu cầu. <a href="page.php?slug=privacy">Chính sách bảo mật</a></p><button class="btn btn-dark">Gửi lời nhắn <i aria-hidden="true" class="bi bi-arrow-up-right ms-3"></i></button></div></div></form></div></div>
